discrete GeothermalWellSystem
port:
    event input real DetectAbnormality;
    event input real MaintenanceComplete;
    event input real SevereFaultDetected;
    event input real FaultFixedAndTested;
state:
    initial state StableOperation
        when entry() then
            statehold(5);
        end;
        when receive(DetectAbnormality) then
            transition(MaintenanceMode);
        end;
        when receive(SevereFaultDetected) then
            transition(MaintenanceMode);
        end;
        when receive(MaintenanceComplete) then
            transition(StableOperation);
        end;
    end;

    state MaintenanceMode
        when entry() then
            statehold(10);
        end;
        when receive(MaintenanceComplete) then
            transition(StableOperation);
        end;
        when receive(FaultFixedAndTested) then
            transition(StableOperation);
        end;
        when receive(SevereFaultDetected) then
            transition(FaultShutdown);
        end;
    end;

    state FaultShutdown
        when entry() then
            statehold(15);
        end;
        when receive(FaultFixedAndTested) then
            transition(StableOperation);
        end;
    end;
end;
end;

discrete HeatExchangerSystem
port:
    event input real TemperatureDeviationDetected;
    event input real TemperatureAdjusted;
    event input real SevereLeakDetected;
    event input real FaultResolvedAndSafetyChecked;
state:
    initial state NormalOperation
        when entry() then
            statehold(5);
        end;
        when receive(TemperatureDeviationDetected) then
            transition(TemperatureAdjustment);
        end;
        when receive(TemperatureAdjusted) then
            transition(NormalOperation);
        end;
    end;

    state TemperatureAdjustment
        when entry() then
            statehold(10);
        end;
        when receive(TemperatureAdjusted) then
            transition(NormalOperation);
        end;
        when receive(SevereLeakDetected) then
            transition(StopOperation);
        end;
    end;

    state StopOperation
        when entry() then
            statehold(15);
        end;
        when receive(FaultResolvedAndSafetyChecked) then
            transition(NormalOperation);
        end;
    end;
end;
end;

discrete PowerGenerationSystem
port:
    event input real SteamSupplyReduced;
    event input real SteamSupplyRestored;
    event input real InsufficientSteamSupply;
    event input real SufficientSteamAvailable;
    event input real MechanicalOrElectricalFaultDetected;
    event input real FaultResolvedAndTested;
state:
    initial state Generating
        when entry() then
            statehold(5);
        end;
        when receive(SteamSupplyReduced) then
            transition(LowLoadOperation);
        end;
        when receive(InsufficientSteamSupply) then
            transition(StandbyMode);
        end;
        when receive(MechanicalOrElectricalFaultDetected) then
            transition(FaultHandling);
        end;
    end;

    state LowLoadOperation
        when entry() then
            statehold(10);
        end;
        when receive(SteamSupplyRestored) then
            transition(Generating);
        end;
        when receive(InsufficientSteamSupply) then
            transition(StandbyMode);
        end;
    end;

    state StandbyMode
        when entry() then
            statehold(15);
        end;
        when receive(SufficientSteamAvailable) then
            transition(Generating);
        end;
    end;

    state FaultHandling
        when entry() then
            statehold(20);
        end;
        when receive(FaultResolvedAndTested) then
            transition(Generating);
        end;
    end;
end;
end;

couple GeothermalPowerSystem
